package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class LargeEnglishNumberWordsTest {
 @Test public void independentLargeSpellingsAndPublicChecks(){Map<Integer,String> cases=new LinkedHashMap<>();cases.put(1001,"one thousand and one");cases.put(10000,"ten thousand");cases.put(10001,"ten thousand and one");cases.put(101105,"one hundred and one thousand one hundred and five");cases.put(999999,"nine hundred and ninety-nine thousand nine hundred and ninety-nine");cases.put(1000000,"one million");cases.put(1000001,"one million and one");cases.put(1021005,"one million twenty-one thousand and five");cases.put(9000105,"nine million one hundred and five");cases.put(9999999,"nine million nine hundred and ninety-nine thousand nine hundred and ninety-nine");cases.put(10000000,"ten million");Checker checker=new Checker();for(var e:cases.entrySet()){assertEquals(e.getValue(),EnglishNumberWords.words(e.getKey()));assertEquals(e.getKey(),EnglishNumberWords.numeral(e.getValue()));for(String id:List.of("englishWordsToNumber","numberToEnglishWords")){Question q=EnglishNumberWords.make(id,e.getKey());q.answers=new String[]{"poison"};assertTrue(checker.check(q,List.of(),List.of(id.equals("englishWordsToNumber")?e.getKey().toString():e.getValue())).correct());assertTrue(EnglishNumberWords.matches(e.getValue().replace(" and "," ").toUpperCase(),e.getValue()));assertFalse(EnglishNumberWords.matches("and "+e.getValue(),e.getValue()));}}assertNull(EnglishNumberWords.numeral("ten million and one"));assertNull(EnglishNumberWords.numeral("one thousand one million"));assertNull(EnglishNumberWords.numeral("one million thousand"));}
 @Test public void largeSpellingErrorsUnderlineOnlyStudentTokensAndHelpUsesPublicDigits(){Question q=EnglishNumberWords.make("numberToEnglishWords",9000105);q.answers=new String[]{"poison"};String raw="nine milion one hundred and five";var feedback=NumberWordFeedback.inspect(q,raw);assertFalse(feedback.correct());assertEquals(List.of(new NumberWordFeedback.Range(5,11)),feedback.ranges());assertTrue(NumberWordFeedback.inspect(q,"nine million one hundred and five").correct());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(7,h.size());assertEquals("english-number-words-large-v1",q.studyGuide.teachingVersion);for(int i=0;i<7;i++)assertTrue(h.step(i).accepts(List.of("9","0","0","0","1","0","5").get(i)));assertEquals("english-number-words-upper-v1",EnglishNumberWords.make("numberToEnglishWords",1000).studyGuide.teachingVersion);assertEquals(8,HelpPlan.forQuestion(EnglishNumberWords.make("englishWordsToNumber",10000000)).size());}
 @Test public void eachYearKeepsBoundsAnd150FreshConditions(){int[] max={0,20,100,1000,10000,1000000,10000000};var pack=GlobalCurriculum.packs("GB").stream().filter(p->p.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();for(int year=1;year<=6;year++)for(String id:List.of("englishWordsToNumber","numberToEnglishWords")){assertTrue(pack.inGrade(id,year));var limits=GlobalCurriculum.limits(pack.id,id,year);assertEquals(max[year],limits.wholeMaximum(-1));if(year<4)continue;Generator g=new Generator(new Random(188+year));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int n=EnglishNumberWords.publicValue(q);assertTrue(n>=0&&n<=max[year]);assertTrue(q.choices.isEmpty());assertFalse(HelpPlan.forQuestion(q).canTransfer());}}}
}
